import{_ as a,o as e,c as r,a2 as i}from"./chunks/framework.BWuWLRhz.js";const u=JSON.parse('{"title":"⚙️ 设置说明","description":"","frontmatter":{},"headers":[],"relativePath":"guide/settings.md","filePath":"guide/settings.md","lastUpdated":1783765259000}'),o={name:"guide/settings.md"};function l(d,t,n,s,h,p){return e(),r("div",null,[...t[0]||(t[0]=[i('<h1 id="⚙️-设置说明" tabindex="-1">⚙️ 设置说明 <a class="header-anchor" href="#⚙️-设置说明" aria-label="Permalink to &quot;⚙️ 设置说明&quot;">​</a></h1><h2 id="🔍-环境配置" tabindex="-1">🔍 环境配置 <a class="header-anchor" href="#🔍-环境配置" aria-label="Permalink to &quot;🔍 环境配置&quot;">​</a></h2><p>设置页面可以查看和配置运行环境：</p><table tabindex="0"><thead><tr><th>项目</th><th>说明</th></tr></thead><tbody><tr><td>🐍 Python</td><td>需要 Python ≥ 3.11，通过 <code>uv</code> 管理</td></tr><tr><td>🎞️ FFmpeg</td><td>用于合并音视频流，可自定义路径</td></tr><tr><td>📦 uv</td><td>Python 包管理器</td></tr></tbody></table><p>如果环境检测不通过，可以手动指定可执行文件路径。</p><h2 id="🎵-音频格式" tabindex="-1">🎵 音频格式 <a class="header-anchor" href="#🎵-音频格式" aria-label="Permalink to &quot;🎵 音频格式&quot;">​</a></h2><p>支持以下音频输出格式：</p><ul><li><strong>m4a</strong> — 默认格式，质量好体积小</li><li><strong>mp3</strong> — 兼容性最好</li><li><strong>flac</strong> — 无损格式</li><li><strong>wav</strong> — 无损无压缩</li></ul><h2 id="🔑-账号登录" tabindex="-1">🔑 账号登录 <a class="header-anchor" href="#🔑-账号登录" aria-label="Permalink to &quot;🔑 账号登录&quot;">​</a></h2><p>通过扫码登录 Bilibili 账号，解锁高画质和大会员内容。</p><p>登录状态会保存在本地，下次启动无需重新登录。</p><h2 id="🌐-代理设置" tabindex="-1">🌐 代理设置 <a class="header-anchor" href="#🌐-代理设置" aria-label="Permalink to &quot;🌐 代理设置&quot;">​</a></h2><p>如果你的网络环境需要代理，可以在设置中配置。</p><p>也可以一键关闭系统代理，避免下载时出现网络问题。</p><h2 id="⚡-解析并发数" tabindex="-1">⚡ 解析并发数 <a class="header-anchor" href="#⚡-解析并发数" aria-label="Permalink to &quot;⚡ 解析并发数&quot;">​</a></h2><p>下载合集、收藏夹等批量内容时，应用会先逐个解析列表里的视频。</p><p>解析并发数控制同时解析多少个视频，默认为 8：</p><ul><li>数值越大，解析越快，下载开始得越早</li><li>如果解析经常失败，可以调小一些（最小为 1，即逐个解析）</li></ul><p>在「设置 → 一般设置」中修改，点击「保存并重新检测」后生效。</p>',19)])])}const _=a(o,[["render",l]]);export{u as __pageData,_ as default};
